public class OpportunityPipelineHandler {
    private static Boolean isRecalculating = false;

    public static void handleTrigger(
        System.TriggerOperation operationType,
        List<Opportunity> newList,
        Map<Id, Opportunity> oldMap,
        List<Opportunity> oldList
    ) {
        if (isRecalculating) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();

        if (operationType == System.TriggerOperation.AFTER_INSERT) {
            if (newList != null) {
                for (Opportunity opp : newList) {
                    if (opp.AccountId != null && opp.IsClosed == false) {
                        accountIds.add(opp.AccountId);
                    }
                }
            }
        } else if (operationType == System.TriggerOperation.AFTER_UPDATE) {
            if (newList != null && oldMap != null) {
                for (Opportunity opp : newList) {
                    Opportunity old = oldMap.get(opp.Id);
                    if (old == null) {
                        continue;
                    }

                    Boolean relevantFieldsChanged = (opp.AccountId != old.AccountId) ||
                                                   (opp.IsClosed != old.IsClosed) ||
                                                   (opp.Amount != old.Amount) ||
                                                   (opp.StageName != old.StageName);

                    if (!relevantFieldsChanged) {
                        continue;
                    }

                    if (old.AccountId != null) {
                        accountIds.add(old.AccountId);
                    }
                    if (opp.AccountId != null) {
                        accountIds.add(opp.AccountId);
                    }
                }
            }
        } else if (operationType == System.TriggerOperation.AFTER_DELETE) {
            if (oldList != null) {
                for (Opportunity opp : oldList) {
                    if (opp.AccountId != null && opp.IsClosed == false) {
                        accountIds.add(opp.AccountId);
                    }
                }
            }
        } else if (operationType == System.TriggerOperation.AFTER_UNDELETE) {
            if (newList != null) {
                for (Opportunity opp : newList) {
                    if (opp.AccountId != null && opp.IsClosed == false) {
                        accountIds.add(opp.AccountId);
                    }
                }
            }
        }

        if (!accountIds.isEmpty()) {
            recomputeAccounts(accountIds);
        }
    }

    private static void recomputeAccounts(Set<Id> accountIds) {
        if (isRecalculating) {
            return;
        }

        isRecalculating = true;
        try {
            List<AggregateResult> results = [
                SELECT AccountId accId, COUNT(Id) cnt, SUM(Amount) amt
                FROM Opportunity
                WHERE AccountId IN :accountIds AND IsClosed = false
                GROUP BY AccountId
            ];

            Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
            Map<Id, Decimal> countByAccount = new Map<Id, Decimal>();

            for (AggregateResult ar : results) {
                Id acctId = (Id) ar.get('accId');

                Decimal totalPipeline = (Decimal) ar.get('amt');
                if (totalPipeline == null) {
                    totalPipeline = 0;
                }

                Integer openCount = (Integer) ar.get('cnt');
                Decimal countDecimal = Decimal.valueOf(String.valueOf(openCount));

                pipelineByAccount.put(acctId, totalPipeline);
                countByAccount.put(acctId, countDecimal);
            }

            List<Account> accountsToUpdate = new List<Account>();
            for (Id acctId : accountIds) {
                Account a = new Account(Id = acctId);
                a.FB_Open_Pipeline__c = pipelineByAccount.containsKey(acctId) ? pipelineByAccount.get(acctId) : 0;
                a.FB_Open_Opportunities__c = countByAccount.containsKey(acctId) ? countByAccount.get(acctId) : 0;
                accountsToUpdate.add(a);
            }

            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate;
            }
        } finally {
            isRecalculating = false;
        }
    }
}
