    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory query = newQueryFactory();
        query.selectField('Account.Name');
        query.setCondition('AccountId IN :accountIds AND IsClosed = false');

        // Replace the selector's default ordering so Amount is the primary sort.
        // NULLS LAST puts opportunities without an Amount after those that have one.
        query.setOrdering('Amount', fflib_QueryFactory.SortOrder.DESCENDING, true);
        query.addOrdering('CloseDate', fflib_QueryFactory.SortOrder.ASCENDING);

        if (maxRecords != null) {
            query.setLimit(maxRecords);
        }

        return (List<Opportunity>) Database.query(query.toSOQL());
    }
}
