public inherited sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = OpportunitiesSelector.newInstance()
            .selectById(opportunityIds);

        fflib_SObjectUnitOfWork unitOfWork =
            (fflib_SObjectUnitOfWork) Application.UnitOfWork.newInstance();

        Integer closedCount = 0;

        for (Opportunity opp : opportunities) {
            if (opp.StageName == 'Closed Won') {
                continue;
            }

            opp.StageName = 'Closed Won';
            opp.CloseDate = Date.today();

            unitOfWork.registerDirty(opp);
            unitOfWork.registerPublishAfterSuccess(new List<SObject>{
                new Deal_Won__e(
                    Opportunity_Id__c = opp.Id,
                    Amount__c = opp.Amount
                )
            });

            closedCount++;
        }

        unitOfWork.commitWork();
        return closedCount;
    }
