public with sharing class HouseholdService {

    private static final String HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME = 'HH_Account';
    private static final String HOUSEHOLD_SYSTEM_ACCOUNT_TYPE = 'Household';

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty.');
        }

        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('members cannot contain a null Contact.');
            }
        }

        Schema.RecordTypeInfo householdRecordTypeInfo = Account.SObjectType.getDescribe()
            .getRecordTypeInfosByDeveloperName()
            .get(HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME);

        if (householdRecordTypeInfo == null) {
            throw new System.UnexpectedException(
                'Household Account record type ' + HOUSEHOLD_RECORD_TYPE_DEVELOPER_NAME + ' not found.'
            );
        }

        Savepoint sp = Database.setSavepoint();

        try {
            Account household = new Account();
            household.RecordTypeId = householdRecordTypeInfo.getRecordTypeId();
            household.npe01__SYSTEM_AccountType__c = HOUSEHOLD_SYSTEM_ACCOUNT_TYPE;
            household.npe01__SYSTEMIsIndividual__c = false;

            // Set Name to an empty string to satisfy the required-field validation
            // while leaving the actual naming to NPSP's before-insert household naming logic.
            // NPSP will replace this with the configured automatic household name.
            household.Name = '';

            insert household;

            for (Contact member : members) {
                member.AccountId = household.Id;
            }
            insert members;

            Account primaryContactUpdate = new Account();
            primaryContactUpdate.Id = household.Id;
            primaryContactUpdate.npe01__One2OneContact__c = members[0].Id;
            update primaryContactUpdate;

            return household.Id;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }
}
