public class SoftCreditService {
    public class SoftCreditException extends Exception {}
    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Map<String, SoftCreditRequest> requestByKey = new Map<String, SoftCreditRequest>();

        for (SoftCreditRequest req : requests) {
            if (req == null) {
                throw new SoftCreditException('Request cannot be null.');
            }
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Opportunity and Contact are required.');
            }
            if (String.isBlank(req.role)) {
                throw new SoftCreditException('Role is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be positive.');
            }

            String key = makeKey(req.opportunityId, req.contactId);
            if (requestByKey.containsKey(key)) {
                throw new SoftCreditException('Duplicate Opportunity/Contact pair in request.');
            }
            requestByKey.put(key, req);
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        Map<Id, Opportunity> oppById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + String.valueOf(req.opportunityId));
            }
            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException('Contact cannot be the opportunity primary contact: ' + String.valueOf(req.contactId));
            }
            if (opp.Amount == null) {
                throw new SoftCreditException('Opportunity amount is null for opportunity: ' + String.valueOf(req.opportunityId));
            }
            if (req.amount == null || req.amount <= 0 || req.amount > opp.Amount) {
                throw new SoftCreditException('Amount must be positive and not exceed the Opportunity amount.');
            }
        }

        Map<Id, Contact> contactById = new Map<Id, Contact>([
            SELECT Id, Name
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        for (SoftCreditRequest req : requests) {
            if (!contactById.containsKey(req.contactId)) {
                throw new SoftCreditException('Contact not found: ' + String.valueOf(req.contactId));
            }
        }

        Map<String, List<OpportunityContactRole>> ocrsByKey = new Map<String, List<OpportunityContactRole>>();
        List<OpportunityContactRole> allOcrs = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ];
        for (OpportunityContactRole ocr : allOcrs) {
            String key = makeKey(ocr.OpportunityId, ocr.ContactId);
            List<OpportunityContactRole> listForPair = ocrsByKey.get(key);
            if (listForPair == null) {
                listForPair = new List<OpportunityContactRole>();
                ocrsByKey.put(key, listForPair);
            }
            listForPair.add(ocr);
        }

        Map<String, List<npsp__Partial_Soft_Credit__c>> pscsByKey = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        List<npsp__Partial_Soft_Credit__c> allPscs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ];
        for (npsp__Partial_Soft_Credit__c psc : allPscs) {
            String key = makeKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            List<npsp__Partial_Soft_Credit__c> listForPair = pscsByKey.get(key);
            if (listForPair == null) {
                listForPair = new List<npsp__Partial_Soft_Credit__c>();
                pscsByKey.put(key, listForPair);
            }
            listForPair.add(psc);
        }

        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> keptOcrByKey = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = makeKey(req.opportunityId, req.contactId);
            List<OpportunityContactRole> existing = ocrsByKey.get(key);
            OpportunityContactRole keep;
            Boolean needsUpsert = false;

            if (existing != null && !existing.isEmpty()) {
                keep = existing[0];
                for (Integer i = 1; i < existing.size(); i++) {
                    ocrsToDelete.add(existing[i]);
                }
                if (keep.Role != req.role) {
                    keep.Role = req.role;
                    needsUpsert = true;
                }
            } else {
                keep = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                needsUpsert = true;
            }

            keptOcrByKey.put(key, keep);
            if (needsUpsert) {
                ocrsToUpsert.add(keep);
            }
        }

        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
        }

        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }

        List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToDelete = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = makeKey(req.opportunityId, req.contactId);
            OpportunityContactRole keptOcr = keptOcrByKey.get(key);
            Contact contact = contactById.get(req.contactId);
            String contactName = contact != null ? contact.Name : '';

            List<npsp__Partial_Soft_Credit__c> existing = pscsByKey.get(key);
            npsp__Partial_Soft_Credit__c psc;
            if (existing != null && !existing.isEmpty()) {
                psc = existing[0];
                for (Integer i = 1; i < existing.size(); i++) {
                    pscsToDelete.add(existing[i]);
                }
            } else {
                psc = new npsp__Partial_Soft_Credit__c();
            }

            psc.npsp__Opportunity__c = req.opportunityId;
            psc.npsp__Contact__c = req.contactId;
            psc.npsp__Amount__c = req.amount;
            psc.npsp__Role_Name__c = req.role;
            psc.npsp__Contact_Role_ID__c = String.valueOf(keptOcr.Id);
            psc.npsp__Contact_Name__c = contactName;

            pscsToUpsert.add(psc);
        }

        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }

        if (!pscsToDelete.isEmpty()) {
            delete pscsToDelete;
        }
    }

    private static String makeKey(Id oppId, Id contactId) {
        return String.valueOf(oppId) + ':' + String.valueOf(contactId);
    }
}
